INSERT INTO t_knowledge_base_connector_ability VALUES ('11563f90-502f-11f1-a198-fa163e5ce7e2', 'KNOWLEDGE_LIST', '知识库列表查询', '用于查询系统中的知识库列表', 'default', NULL);
INSERT INTO t_knowledge_base_connector_ability VALUES ('115b9ec5-502f-11f1-a198-fa163e5ce7e2', 'RETRIEVE', '知识检索', '用于从知识库中进行知识检索', 'default', '{"search_mode_list":[{"search_mode":"doc","search_mode_name":"语义检索","search_mode_name_en":"Semantic Retrieval","summary":"使用向量检索技术检索知识文档","summary_en":"Using vector retrieval technology to retrieve knowledge documents.","description":"使用向量检索技术检索，对文档及结构化数据中知识进行检索，召回与用户意图相关性高的切片内容，推荐在需要结合上下文相关性、并对用户意图理解场景中使用。","description_en":"Using vector retrieval technology to search for knowledge within documents and structured data, it retrieves slices of content that are highly relevant to user intent. This method is recommended for scenarios where contextual relevance needs to be integrated and a deep understanding of user intent is required."},{"search_mode":"keyword","search_mode_name":"关键词检索","search_mode_name_en":"Keyword Retrieval","summary":"使用倒排检索技术检索知识文档","summary_en":"Using inverted retrieval technology to search for knowledge documents.","description":"使用倒排检索技术，对文档及结构化数据中知识进行检索，召回与Query关键词匹配度高的切片内容，推荐在需要用户提问关键词匹配度高的场景中使用。","description_en":"Using inverted retrieval technology, knowledge within documents and structured data is retrieved, and slices of content with high matching degree to the query keywords are recalled. This method is recommended for scenarios where high keyword matching degree in user queries is required. "},{"search_mode":"mix","search_mode_name":"混合检索","search_mode_name_en":"Mix Retrieval","summary":"使用向量检索和关键词检索混合检索知识文档","summary_en":"Using vector retrieval and keyword retrieval to retrieve knowledge documents.","description":"使用向量检索和关键词检索两种策略混合检索知识库，推荐在需要兼顾用户意图理解及关键词匹配度场景中使用。","description_en":"Use a hybrid retrieval strategy that combines vector retrieval and keyword retrieval for the knowledge base. This approach is recommended for scenarios where both user intent understanding and keyword matching are important. "},{"search_mode":"faq","search_mode_name":"FAQ检索","search_mode_name_en":"FAQ Retrieval","summary":"使用向量检索技术检索FAQ","summary_en":"Using vector retrieval technology to search FAQs.","description":"使用向量检索技术检索，对FAQ问答对中知识进行检索，召回与用户意图相关性高的FAQ内容，推荐在需要结合上下文相关性、并对用户意图理解场景中使用。","description_en":"Using vector retrieval technology to search for knowledge within FAQ pairs, it retrieves FAQ content that is highly relevant to the users intent. This method is recommended for scenarios where contextual relevance needs to be combined and a deep understanding of the users intent is required."}]}');
