INSERT INTO t_knowledge_base_connector VALUES ('General', 'General', 'data:image/svg+xml;base64,', '用于对接用户自开发知识库平台', 'HC,HCS,SIMPLE', 'Outside', '[{"code":"endpoint","name":"服务地址","need":"Y","type":"STRING","remark":"知识库服务的入口地址","pattern":"^.*$"},{"code":"apiKey","name":"鉴权信息密钥","need":"Y","type":"SECRET","remark":"认证鉴权，在http/https的请求header中添加的用户鉴权信息密钥"},{"code":"knowledge_base_detail_url","name":"知识库详情页面链接","need":"Y","type":"STRING","remark":"知识库详情页面链接，如https://xxxx?id={{id}}。注意使用占位符{{id}}表示知识库ID，否则无法跳转到对应的知识库页面","pattern":"^.*$"}]', '通用知识库', 'system', 'system', 'system', 'system', 0, 'system', 'system', 0, 'system', 'system');
INSERT INTO t_knowledge_base_connector VALUES ('KooSearch', 'KooSearch', 'data:image/svg+xml;base64,', '用于对接企业搜索服务：KooSearch', 'HC', 'Outside', '[{"code":"endpoint","name":"服务地址","need":"Y","type":"STRING","remark":"APIG接口的地址","pattern":"^.*$"},{"code":"project_id","name":"项目id","need":"Y","type":"STRING","remark":"用户登录账号的项目id，可以在个人信息中‘我的凭证’处查看","pattern":"^[a-z0-9-]*$"},{"code":"application_id","name":"应用id","need":"Y","type":"STRING","remark":"KooSearch知识库平台的应用id，在KooSearch平台查看","pattern":"^[a-z0-9-]*$"},{"code":"AppCode","name":"APIG凭证","need":"Y","type":"SECRET","remark":"KooSearch平台接口绑定的APIG凭证的AppCode，用于认证鉴权"},{"code":"knowledge_base_detail_url","name":"知识库详情页面链接","need":"Y","type":"STRING","remark":"知识库详情页面链接，如https://xxxx?id={{id}}。注意使用占位符{{id}}表示知识库ID，否则无法跳转到对应的知识库页面","pattern":"^.*$"}]', '第三方KooSearch知识库', 'system', 'system', 'system', 'system', 0, 'system', 'system', 0, 'system', 'system');
