INSERT INTO t_knowledge_base_connector VALUES ('LakeSearch', 'LakeSearch', 'data:image/svg+xml;base64,', '用于对接企业搜索服务(LakeSearch)，支持对接多个不同的LakeSearch集群', 'HCS,SIMPLE', 'Outside', '[{"code":"endpoint","name":"服务地址","need":"Y","type":"STRING","remark":"LakeSearch集群地址","pattern":"^.*$"},{"code":"user_name","name":"用户名","need":"N","type":"STRING","remark":"LakeSearch集群所在MRS服务的用户账号，如果MRS服务未开启安全模式，则无需填写"},{"code":"password","name":"用户密码","need":"N","type":"SECRET","remark":"LakeSearch集群所在MRS服务的用户密码，如果MRS服务未开启安全模式，则无需填写"},{"code":"knowledge_base_detail_url","name":"知识库详情页面链接","need":"Y","type":"STRING","remark":"知识库详情页面链接，如https://xxxx?id={{id}}。注意使用占位符{{id}}表示知识库ID，否则无法跳转到对应的知识库页面","pattern":"^.*$"}]', 'lakeSearch知识库', 'system', 'system', 'system', 'system', 0, 'system', 'system', 0, 'system', 'system');
