INSERT INTO t_knowledge_i18n_resource VALUES (29, 'ability.RETRIEVE.search_mode.doc.name', 'zh-cn', '语义检索');
INSERT INTO t_knowledge_i18n_resource VALUES (30, 'ability.RETRIEVE.search_mode.doc.summary', 'zh-cn', '使用向量检索技术检索知识文档');
INSERT INTO t_knowledge_i18n_resource VALUES (31, 'ability.RETRIEVE.search_mode.doc.description', 'zh-cn', '使用向量检索技术检索，对文档及结构化数据中知识进行检索，召回与用户意图相关性高的切片内容，推荐在需要结合上下文相关性、并对用户意图理解场景中使用。');
INSERT INTO t_knowledge_i18n_resource VALUES (32, 'ability.RETRIEVE.search_mode.keyword.name', 'zh-cn', '关键词检索');
INSERT INTO t_knowledge_i18n_resource VALUES (33, 'ability.RETRIEVE.search_mode.keyword.summary', 'zh-cn', '使用倒排检索技术检索知识文档');
INSERT INTO t_knowledge_i18n_resource VALUES (34, 'ability.RETRIEVE.search_mode.keyword.description', 'zh-cn', '使用倒排检索技术，对文档及结构化数据中知识进行检索，召回与Query关键词匹配度高的切片内容，推荐在需要用户提问关键词匹配度高的场景中使用。');
INSERT INTO t_knowledge_i18n_resource VALUES (35, 'ability.RETRIEVE.search_mode.mix.name', 'zh-cn', '混合检索');
INSERT INTO t_knowledge_i18n_resource VALUES (36, 'ability.RETRIEVE.search_mode.mix.summary', 'zh-cn', '使用向量检索和关键词检索混合检索知识文档');
INSERT INTO t_knowledge_i18n_resource VALUES (37, 'ability.RETRIEVE.search_mode.mix.description', 'zh-cn', '使用向量检索和关键词检索两种策略混合检索知识库，推荐在需要兼顾用户意图理解及关键词匹配度场景中使用。');
INSERT INTO t_knowledge_i18n_resource VALUES (38, 'ability.RETRIEVE.search_mode.faq.name', 'zh-cn', 'FAQ检索');
INSERT INTO t_knowledge_i18n_resource VALUES (39, 'ability.RETRIEVE.search_mode.faq.summary', 'zh-cn', '使用向量检索技术检索FAQ');
INSERT INTO t_knowledge_i18n_resource VALUES (40, 'ability.RETRIEVE.search_mode.faq.description', 'zh-cn', '使用向量检索技术检索，对FAQ问答对中知识进行检索，召回与用户意图相关性高的FAQ内容，推荐在需要结合上下文相关性、并对用户意图理解场景中使用。');
