INSERT INTO t_knowledge_i18n_resource VALUES (62, 'connector.KooSearch.param.application_id.name', 'en-us', 'Application ID');
INSERT INTO t_knowledge_i18n_resource VALUES (63, 'connector.KooSearch.param.application_id.remark', 'en-us', 'Application ID of the KooSearch platform, viewable on the KooSearch platform.');
