INSERT INTO t_knowledge_i18n_resource VALUES (67, 'connector.KooSearch.param.knowledge_base_detail_url.remark', 'en-us', 'Link to the knowledge base detail page, e.g., https://xxxx?id={{id}}. Note: use {{id}} as a placeholder to ensure correct redirection.');
INSERT INTO t_knowledge_i18n_resource VALUES (68, 'connector.His.description', 'en-us', 'Users connect to Agent Builders internal platform knowledge base.');
INSERT INTO t_knowledge_i18n_resource VALUES (69, 'ability.RETRIEVE.search_mode.doc.name', 'en-us', 'Semantic Retrieval');
INSERT INTO t_knowledge_i18n_resource VALUES (70, 'ability.RETRIEVE.search_mode.doc.summary', 'en-us', 'Using vector retrieval technology to retrieve knowledge documents.');
INSERT INTO t_knowledge_i18n_resource VALUES (71, 'ability.RETRIEVE.search_mode.doc.description', 'en-us', 'Using vector retrieval technology to search for knowledge within documents and structured data, it retrieves slices of content that are highly relevant to user intent. This method is recommended for scenarios where contextual relevance needs to be integrated and a deep understanding of user intent is required.');
INSERT INTO t_knowledge_i18n_resource VALUES (72, 'ability.RETRIEVE.search_mode.keyword.name', 'en-us', 'Keyword Retrieval');
INSERT INTO t_knowledge_i18n_resource VALUES (73, 'ability.RETRIEVE.search_mode.keyword.summary', 'en-us', 'Using inverted retrieval technology to search for knowledge documents.');
INSERT INTO t_knowledge_i18n_resource VALUES (74, 'ability.RETRIEVE.search_mode.keyword.description', 'en-us', 'Using inverted retrieval technology, knowledge within documents and structured data is retrieved, and slices of content with high matching degree to the query keywords are recalled. This method is recommended for scenarios where high keyword matching degree in user queries is required.');
INSERT INTO t_knowledge_i18n_resource VALUES (75, 'ability.RETRIEVE.search_mode.mix.name', 'en-us', 'Mix Retrieval');
INSERT INTO t_knowledge_i18n_resource VALUES (76, 'ability.RETRIEVE.search_mode.mix.summary', 'en-us', 'Using vector retrieval and keyword retrieval to retrieve knowledge documents.');
INSERT INTO t_knowledge_i18n_resource VALUES (77, 'ability.RETRIEVE.search_mode.mix.description', 'en-us', 'Use a hybrid retrieval strategy that combines vector retrieval and keyword retrieval for the knowledge base. This approach is recommended for scenarios where both user intent understanding and keyword matching are important.');
INSERT INTO t_knowledge_i18n_resource VALUES (78, 'ability.RETRIEVE.search_mode.faq.name', 'en-us', 'FAQ Retrieval');
INSERT INTO t_knowledge_i18n_resource VALUES (79, 'ability.RETRIEVE.search_mode.faq.summary', 'en-us', 'Using vector retrieval technology to search FAQs.');
INSERT INTO t_knowledge_i18n_resource VALUES (80, 'ability.RETRIEVE.search_mode.faq.description', 'en-us', 'Using vector retrieval technology to search for knowledge within FAQ pairs, it retrieves FAQ content that is highly relevant to the users intent. This method is recommended for scenarios where contextual relevance needs to be combined and a deep understanding of the users intent is required.');
